INSERT INTO exercises (external_id, name, muscle_group, secondary_muscles, equipment, category, level, instructions) VALUES
('One-Arm_Open_Palm_Kettlebell_Clean', 'One-Arm Open Palm Kettlebell Clean', 'legs', ARRAY['arms','legs','back','legs','shoulders']::text[], 'kettlebell', 'strength', 'intermediate', 'Place one kettlebell between your feet. Grab the handle with one hand and raise the kettlebell rapidly, let it flip so that the ball of the kettlebell lands in the palm of your hand. Throw the kettlebell out in front of you and catch the handle with one hand. Take the kettlebell to the floor and repeat. Make sure to work both arms.'),
('One-Arm_Overhead_Kettlebell_Squats', 'One-Arm Overhead Kettlebell Squats', 'legs', ARRAY['legs','legs','legs','shoulders']::text[], 'kettlebell', 'strength', 'expert', 'Clean and press a kettlebell with one arm. Clean the kettlebell to your shoulder by extending through the legs and hips as you pull the kettlebell towards your shoulder. Rotate your wrist as you do so. Press the weight overhead by extending through the elbow.This will be your starting position. Looking straight ahead and keeping a kettlebell locked out above you, flex the knees and hips and lower your torso between your legs, keeping your head and chest up. Pause at the bottom position for a sec'),
('One-Arm_Side_Deadlift', 'One-Arm Side Deadlift', 'legs', ARRAY['core','legs','legs','legs','back','back']::text[], 'barbell', 'strength', 'expert', 'Stand to the side of a barbell next to its center. Bend your knees and lower your body until you are able to reach the barbell. Grasp the bar as if you were grabbing a briefcase (palms facing you since the bar is sideways). You may need a wrist wrap if you are using a significant amount of weight. This is your starting position. Use your legs to help lift the barbell up while exhaling. Your arms should extend fully as bring the barbell up until you are in a standing position. Slowly bring the ba'),
('One-Arm_Side_Laterals', 'One-Arm Side Laterals', 'shoulders', ARRAY[]::text[], 'dumbbell', 'strength', 'beginner', 'Pick a dumbbell and place it in one of your hands. Your non lifting hand should be used to grab something steady such as an incline bench press. Lean towards your lifting arm and away from the hand that is gripping the incline bench as this will allow you to keep your balance. Stand with a straight torso and have the dumbbell by your side at arm''s length with the palm of the hand facing you. This will be your starting position. While maintaining the torso stationary (no swinging), lift the dumb'),
('One-Legged_Cable_Kickback', 'One-Legged Cable Kickback', 'legs', ARRAY['legs']::text[], 'cable', 'strength', 'intermediate', 'Hook a leather ankle cuff to a low cable pulley and then attach the cuff to your ankle. Face the weight stack from a distance of about two feet, grasping the steel frame for support. While keeping your knees and hips bent slightly and your abs tight, contract your glutes to slowly "kick" the working leg back in a semicircular arc as high as it will comfortably go as you breathe out. Tip: At full extension, squeeze your glutes for a second in order to achieve a peak contraction. Now slowly bring '),
('One_Arm_Against_Wall', 'One Arm Against Wall', 'back', ARRAY[]::text[], 'other', 'stretching', 'beginner', 'From a standing position, place a bent arm against a wall or doorway. Slowly lean toward your arm until you feel a stretch in your lats.'),
('One_Arm_Chin-Up', 'One Arm Chin-Up', 'back', ARRAY['arms','arms','back']::text[], 'other', 'strength', 'expert', 'For this exercise, start out by placing a towel around a chin up bar. Grab the chin-up bar with your palm facing you. One hand will be grabbing the chin-up bar and the other will be grabbing the towel. Bring your torso back around 30 degrees or so while creating a curvature on your lower back and sticking your chest out. This is your starting position.v Pull your torso up until the bar touches your upper chest by drawing the shoulders and the upper arms down and back. Exhale as you perform this '),
('One_Arm_Dumbbell_Bench_Press', 'One Arm Dumbbell Bench Press', 'chest', ARRAY['shoulders','arms']::text[], 'dumbbell', 'strength', 'beginner', 'Lie down on a flat bench with a dumbbell in one hand on top of your thigh. By using your thigh to help you get the dumbbell up, clean the dumbbell up so that you can hold it in front of you at shoulder width. Use the hand you are not lifting with to help position the dumbbell over you properly. Once at shoulder width, rotate your wrist forward so that the palm of your hand is facing away from you. This will be your starting position. Bring down the weights slowly to your side as you breathe in. '),
('One_Arm_Dumbbell_Preacher_Curl', 'One Arm Dumbbell Preacher Curl', 'arms', ARRAY[]::text[], 'dumbbell', 'strength', 'beginner', 'Grab a dumbbell with the right arm and place the upper arm on top of the preacher bench or the incline bench. The dumbbell should be held at shoulder length. This will be your starting position. As you breathe in, slowly lower the dumbbell until your upper arm is extended and the biceps is fully stretched. As you exhale, use the biceps to curl the weight up until your biceps is fully contracted and the dumbbell is at shoulder height. Again, remember that to ensure full contraction you need to br'),
('One_Arm_Floor_Press', 'One Arm Floor Press', 'arms', ARRAY['chest','shoulders']::text[], 'barbell', 'strength', 'intermediate', 'Lie down on a flat surface with your back pressing against the floor or an exercise mat. Make sure your knees are bent. Have a partner hand you the bar on one hand. When starting, your arm should be just about fully extended, similar to the starting position of a barbell bench press. However, this time your grip will be neutral (palms facing your torso). Make sure the hand you are not using to lift the weight is placed by your side. Begin the exercise by lowering the barbell until your elbow tou'),
('One_Arm_Lat_Pulldown', 'One Arm Lat Pulldown', 'back', ARRAY['arms','back']::text[], 'cable', 'strength', 'beginner', 'Select an appropriate weight and adjust the knee pad to help keep you down. Grasp the handle with a pronated grip. This will be your starting position. Pull the handle down, squeezing your elbow to your side as you flex the elbow. Pause at the bottom of the motion, and then slowly return the handle to the starting position. For multiple repetitions, avoid completely returning the weight to keep tension on the muscles being worked.'),
('One_Arm_Pronated_Dumbbell_Triceps_Extension', 'One Arm Pronated Dumbbell Triceps Extension', 'arms', ARRAY[]::text[], 'dumbbell', 'strength', 'beginner', 'Lie flat on a bench while holding a dumbbell at arms length. Your arm should be perpendicular to your body. The palm of your hand should be facing towards your feet as a pronated grip is required to perform this exercise. Place your non lifting hand on your bicep for support. Slowly begin to lower the dumbbell down as you breathe in. Then, begin lifting the dumbbell upward as you contract the triceps. Remember to breathe out during the concentric (lifting part of the exercise). Repeat until you '),
('One_Arm_Supinated_Dumbbell_Triceps_Extension', 'One Arm Supinated Dumbbell Triceps Extension', 'arms', ARRAY[]::text[], 'dumbbell', 'strength', 'beginner', 'Lie flat on a bench while holding a dumbbell at arms length. Your arm should be perpendicular to your body. The palm of your hand should be facing towards your face as a supinated grip is required to perform this exercise. Place your non lifting hand on your bicep for support. Slowly begin to lower the dumbbell down as you breathe in. Then, begin lifting the dumbbell upward as you contract the triceps. Remember to breathe out during the concentric (lifting part of the exercise). Repeat until you'),
('One_Half_Locust', 'One Half Locust', 'legs', ARRAY['core','arms','chest']::text[], 'other', 'stretching', 'beginner', 'Lie facedown on the floor. Put your left hand under your left hipbone to pad your hip and pubic bone. Bend your right knee so you can hold the foot in your right hand. Lift the foot in the air and simultaneously lift your shoulders off the floor. This also stretches the right hip flexor and the chest and shoulders. Switch sides. If it doesn''t bother your back, you can try it with both arms and legs at the same time.'),
('One_Handed_Hang', 'One Handed Hang', 'back', ARRAY['arms']::text[], 'other', 'stretching', 'beginner', 'Grab onto a chinup bar with one hand, using a pronated grip. Keep your feet on the floor or a step. Allow the majority of your weight to hang from that hand, while keeping your feet on the ground. Hold for 10-20 seconds and switch sides.'),
('One_Knee_To_Chest', 'One Knee To Chest', 'legs', ARRAY['legs','back']::text[], 'other', 'stretching', 'beginner', 'Start off by lying on the floor. Extend one leg straight and pull the other knee to your chest. Hold under the knee joint to protect the kneecap. Gently tug that knee toward your nose. Switch sides. This stretches the buttocks and lower back of the bent leg and the hip flexor of the straight leg.'),
('One_Leg_Barbell_Squat', 'One Leg Barbell Squat', 'legs', ARRAY['legs','legs','legs']::text[], 'barbell', 'strength', 'expert', 'Start by standing about 2 to 3 feet in front of a flat bench with your back facing the bench. Have a barbell in front of you on the floor. Tip: Your feet should be shoulder width apart from each other. Bend the knees and use a pronated grip with your hands being wider than shoulder width apart from each other to lift the barbell up until you can rest it on your chest. Then lift the barbell over your head and rest it on the base of your neck. Move one foot back so that your toe is resting on the '),
('Open_Palm_Kettlebell_Clean', 'Open Palm Kettlebell Clean', 'legs', ARRAY['legs','back','legs','shoulders']::text[], 'kettlebell', 'strength', 'expert', 'Place one kettlebell between your feet. Clean the kettlebell by extending through the legs and hips as you raise the kettlebell towards your shoulders. Release the kettlebell as it comes up, and let it flip so that the ball of the kettlebell lands in the palms of your hands. Release the kettlebell out in front of you and catch the handle with both hands. Lower the kettlebell to the starting position and repeat.'),
('Otis-Up', 'Otis-Up', 'core', ARRAY['chest','shoulders','arms']::text[], 'other', 'strength', 'beginner', 'Secure your feet and lay back on the floor. Your knees should be bent. Hold a weight with both hands to your chest. This will be your starting position. Initiate the movement by flexing the hips and spine to raise your torso up from the ground. As you move up, press the weight up so that it is above your head at the top of the movement. Return the weight to your chest as you reverse the sit-up motion, ensuring not to go all the way down to the floor.'),
('Overhead_Cable_Curl', 'Overhead Cable Curl', 'arms', ARRAY[]::text[], 'cable', 'strength', 'intermediate', 'To begin, set a weight that is comfortable on each side of the pulley machine. Note: Make sure that the amount of weight selected is the same on each side. Now adjust the height of the pulleys on each side and make sure that they are positioned at a height higher than that of your shoulders. Stand in the middle of both sides and use an underhand grip (palms facing towards the ceiling) to grab each handle. Your arms should be fully extended and parallel to the floor with your feet positioned shou'),
('Overhead_Lat', 'Overhead Lat', 'back', ARRAY['arms']::text[], 'other', 'stretching', 'expert', 'Sit upright on the floor with your partner behind you. Raise one arm straight up, and flex the elbow, attempting to touch your hand to your back. Your parner should hold your tricep and wrist. This will be your starting position. Attempt to pull your upper arm to your side as your partner prevents you from doing actually doing so. After 10-20 seconds, relax the arm and allow your partner to further stretch the lat by applying gentle pressure to the tricep. Hold for 10-20 seconds, and then switch'),
('Overhead_Slam', 'Overhead Slam', 'back', ARRAY[]::text[], 'other', 'plyometrics', 'beginner', 'Hold a medine ball with both hands and stand with your feet at shoulder width. This will be your starting position. Initiate the countermovement by raising the ball above your head and fully extending your body. Reverse the motion, slamming the ball into the ground directly in front of you as hard as you can. Receive the ball with both hands on the bounce and repeat the movement.'),
('Overhead_Squat', 'Overhead Squat', 'legs', ARRAY['core','legs','legs','legs','back','shoulders','arms']::text[], 'barbell', 'olympic weightlifting', 'expert', 'Start out by having a barbell in front of you on the floor. Your feet should be wider than shoulder width apart from each other. Bend the knees and use a pronated grip (palms facing you) to grab the barbell. Your hands should be at a wider than shoulder width apart from each other before lifting. Once you are positioned, lift the barbell up until you can rest it on your chest. Move the barbell over and slightly behind your head and make sure your arms are fully extended. Keep your head up at all'),
('Overhead_Stretch', 'Overhead Stretch', 'core', ARRAY['chest','arms','back','arms']::text[], 'other', 'stretching', 'beginner', 'Standing straight up, lace your fingers together and open your palms to the ceiling. Keep your shoulders down as you extend your arms up. To create a full torso stretch, pull your tailbone down and stabilize your torso as you do this. Stretch the muscles on both the front and the back of the torso.'),
('Overhead_Triceps', 'Overhead Triceps', 'arms', ARRAY['back']::text[], 'bodyweight', 'stretching', 'expert', 'Sit upright on the floor with your partner behind you. Raise one arm straight up, and flex the elbow, attempting to touch your hand to your back. Your parner should hold your elbow and wrist. This will be your starting position. Attempt to extend the arm straight into the air as your partner prevents you from doing actually doing so. After 10-20 seconds, relax the arm and allow your partner to further stretch the tricep by applying gentle pressure to the wrist. Hold for 10-20 seconds, and then s'),
('Pallof_Press', 'Pallof Press', 'core', ARRAY['chest','shoulders','arms']::text[], 'cable', 'strength', 'beginner', 'Connect a standard handle to a tower, and—if possible—position the cable to shoulder height. If not, a low pulley will suffice. With your side to the cable, grab the handle with both hands and step away from the tower. You should be approximately arm''s length away from the pulley, with the tension of the weight on the cable. With your feet positioned hip-width apart and knees slightly bent, hold the cable to the middle of your chest. This will be your starting position. Press the cable away fro'),
('Pallof_Press_With_Rotation', 'Pallof Press With Rotation', 'core', ARRAY['chest','shoulders','arms']::text[], 'cable', 'strength', 'beginner', 'Connect a standard handle to a tower, and position the cable to shoulder height. With your side to the cable, grab the handle with one hand and step away from the tower. You should be approximately arm''s length away from the pulley, with the tension of the weight on the cable. Align outstretched arm with cable. With your feet positioned hip-width apart, pull the cable into your chest and grab the handle with your other hand. Both hands should be on the handle at this time. Facing forward, press'),
('Palms-Down_Dumbbell_Wrist_Curl_Over_A_Bench', 'Palms-Down Dumbbell Wrist Curl Over A Bench', 'arms', ARRAY[]::text[], 'dumbbell', 'strength', 'beginner', 'Start out by placing two dumbbells on one side of a flat bench. Kneel down on both of your knees so that your body is facing the flat bench. Use your arms to grab both of the dumbbells with a pronated grip (palms facing down) and bring them up so that your forearms are resting against the flat bench. Your wrists should be hanging over the edge. Start out by curling your wrist upwards and exhaling. Slowly lower your wrists back down to the starting position while inhaling. Your forearms should be'),
('Palms-Down_Wrist_Curl_Over_A_Bench', 'Palms-Down Wrist Curl Over A Bench', 'arms', ARRAY[]::text[], 'barbell', 'strength', 'beginner', 'Start out by placing a barbell on one side of a flat bench. Kneel down on both of your knees so that your body is facing the flat bench. Use your arms to grab the barbell with a pronated grip (palms down) and bring them up so that your forearms are resting against the flat bench. Your wrists should be hanging over the edge. Start out by curling your wrist upwards and exhaling. Slowly lower your wrists back down to the starting position while inhaling. Your forearms should be stationary as your w'),
('Palms-Up_Barbell_Wrist_Curl_Over_A_Bench', 'Palms-Up Barbell Wrist Curl Over A Bench', 'arms', ARRAY[]::text[], 'barbell', 'strength', 'beginner', 'Start out by placing a barbell on one side of a flat bench. Kneel down on both of your knees so that your body is facing the flat bench. Use your arms to grab the barbell with a supinated grip (palms up) and bring them up so that your forearms are resting against the flat bench. Your wrists should be hanging over the edge. Start out by curling your wrist upwards and exhaling. Slowly lower your wrists back down to the starting position while inhaling. Your forearms should be stationary as your wr'),
('Palms-Up_Dumbbell_Wrist_Curl_Over_A_Bench', 'Palms-Up Dumbbell Wrist Curl Over A Bench', 'arms', ARRAY[]::text[], 'dumbbell', 'strength', 'beginner', 'Start out by placing two dumbbells on one side of a flat bench. Kneel down on both of your knees so that your body is facing the flat bench. Use your arms to grab both of the dumbbells with a supinated grip (palms up) and bring them up so that your forearms are resting against the flat bench. Your wrists should be hanging over the edge. Start out by curling your wrist upwards and exhaling. Slowly lower your wrists back down to the starting position while inhaling. Make sure to inhale during this'),
('Parallel_Bar_Dip', 'Parallel Bar Dip', 'arms', ARRAY['chest','shoulders']::text[], 'other', 'strength', 'beginner', 'Stand between a set of parallel bars. Place a hand on each bar, and then take a small jump to help you get into the starting position with your arms locked out. Begin by flexing the elbow, lowering your body until your arms break 90 degrees. Avoid swinging, and maintain good posture throughout the descent. Reverse the motion by extending the elbow, pushing yourself back up into the starting position. Repeat for the desired number of repetitions.'),
('Pelvic_Tilt_Into_Bridge', 'Pelvic Tilt Into Bridge', 'back', ARRAY[]::text[], 'other', 'stretching', 'intermediate', 'Lie down with your feet on the floor, heels directly under your knees. Lift only your tailbone to the ceiling to stretch your lower back. (Don''t lift the entire spine yet.) Pull in your stomach. To go into a bridge, lift the entire spine except the neck.'),
('Peroneals-SMR', 'Peroneals-SMR', 'legs', ARRAY[]::text[], 'other', 'stretching', 'intermediate', 'Lay on your side, supporting your weight on your forearm and on a foam roller placed on the outside of your lower leg. Your upper leg can either be on top of your lower leg, or you can cross it in front of you. This will be your starting position. Raise your hips off of the ground and begin to roll from below the knee to above the ankle on the side of your leg, pausing at points of tension for 10-30 seconds. Repeat on the other leg.'),
('Peroneals_Stretch', 'Peroneals Stretch', 'legs', ARRAY[]::text[], 'other', 'stretching', 'intermediate', 'In a seated position, loop a belt, rope, or band around one foot. This will be your starting position. With the leg extended and the heel off of the ground, pull on the belt so that the foot is inverted, with the inside of the foot being pulled towards you. Hold for 10-20 seconds, and then switch sides.'),
('Physioball_Hip_Bridge', 'Physioball Hip Bridge', 'legs', ARRAY['legs']::text[], 'other', 'strength', 'beginner', 'Lay on a ball so that your upper back is on the ball with your hips unsupported. Both feet should be flat on the floor, hip width apart or wider. This will be your starting position. Begin by extending the hips using your glutes and hamstrings, raising your hips upward as you bridge. Pause at the top of the motion and return to the starting position.'),
('Pin_Presses', 'Pin Presses', 'arms', ARRAY['chest','arms','back','back','shoulders']::text[], 'barbell', 'powerlifting', 'intermediate', 'Pin presses remove the eccentric phase of the bench press, developing starting strength. They also allow you to train a desired range of motion. The bench should be set up in a power rack. Set the pins to the desired point in your range of motion, whether it just be lockout or an inch off of your chest. The bar should be moved to the pins and prepared for lifting. Begin by lying on the bench, with the bar directly above the contact point during your regular bench. Tuck your feet underneath you a'),
('Piriformis-SMR', 'Piriformis-SMR', 'legs', ARRAY[]::text[], 'other', 'stretching', 'intermediate', 'Sit with your buttocks on top of a foam roll. Bend your knees, and then cross one leg so that the ankle is over the knee. This will be your starting position. Shift your weight to the side of the crossed leg, rolling over the buttocks until you feel tension in your upper glute. You may assist the stretch by using one hand to pull the bent knee towards your chest. Hold this position for 10-30 seconds, and then switch sides.'),
('Plank', 'Plank', 'core', ARRAY[]::text[], 'bodyweight', 'strength', 'beginner', 'Get into a prone position on the floor, supporting your weight on your toes and your forearms. Your arms are bent and directly below the shoulder. Keep your body straight at all times, and hold this position as long as possible. To increase difficulty, an arm or leg can be raised.'),
('Plate_Pinch', 'Plate Pinch', 'arms', ARRAY[]::text[], 'other', 'strength', 'intermediate', 'Grab two wide-rimmed plates and put them together with the smooth sides facing outward Use your fingers to grip the outside part of the plate and your thumb for the other side thus holding both plates together. This is the starting position. Squeeze the plate with your fingers and thumb. Hold this position for as long as you can. Repeat for the recommended amount of sets prescribed in your program. Switch arms and repeat the movements.'),
('Plate_Twist', 'Plate Twist', 'core', ARRAY[]::text[], 'other', 'strength', 'intermediate', 'Lie down on the floor or an exercise mat with your legs fully extended and your upper body upright. Grab the plate by its sides with both hands out in front of your abdominals with your arms slightly bent. Slowly cross your legs near your ankles and lift them up off the ground. Your knees should also be bent slightly. Note: Move your upper body back slightly to help keep you balanced turning this exercise. This is the starting position. Move the plate to the left side and touch the floor with it'),
('Platform_Hamstring_Slides', 'Platform Hamstring Slides', 'legs', ARRAY['legs']::text[], 'other', 'strength', 'beginner', 'For this movement a wooden floor or similar is needed. Lay on your back with your legs extended. Place a gym towel or a light weight underneath your heel. This will be your starting position. Begin the movement by flexing the knee, keeping your other leg straight. Continue bringing the heel closer to you, sliding it on the floor. At full knee flexion, reverse the movement to return to the starting position.'),
('Plie_Dumbbell_Squat', 'Plie Dumbbell Squat', 'legs', ARRAY['core','legs','legs','legs']::text[], 'dumbbell', 'strength', 'beginner', 'Hold a dumbbell at the base with both hands and stand straight up. Move your legs so that they are wider than shoulder width apart from each other with your knees slightly bent. Your toes should be facing out. Note: Your arms should be stationary while performing the exercise. This is the starting position. Slowly bend the knees and lower your legs until your thighs are parallel to the floor. Make sure to inhale as this is the eccentric part of the exercise. Press mainly with the heel of the foo'),
('Plyo_Kettlebell_Pushups', 'Plyo Kettlebell Pushups', 'chest', ARRAY['shoulders','arms']::text[], 'kettlebell', 'strength', 'expert', 'Place a kettlebell on the floor. Place yourself in a pushup position, on your toes with one hand on the ground and one hand holding the kettlebell, with your elbows extended. This will be your starting position. Begin by lowering yourself as low as you can, keeping your back straight. Quickly and forcefully reverse direction, pushing yourself up to the other side of the kettlebell, switching hands as you do so. Continue the movement by descending and repeating the movement back and forth.'),
('Plyo_Push-up', 'Plyo Push-up', 'chest', ARRAY['shoulders','arms']::text[], 'bodyweight', 'plyometrics', 'beginner', 'Move into a prone position on the floor, supporting your weight on your hands and toes. Your arms should be fully extended with the hands around shoulder width. Keep your body straight throughout the movement. This will be your starting position. Descend by flexing at the elbow, lowering your chest towards the ground. At the bottom, reverse the motion by pushing yourself up through elbow extension as quickly as possible. Attempt to push your upper body up until your hands leave the ground. Retur'),
('Posterior_Tibialis_Stretch', 'Posterior Tibialis Stretch', 'legs', ARRAY[]::text[], 'other', 'stretching', 'intermediate', 'In a seated position, loop a belt, rope, or band around one foot. This will be your starting position. With the leg extended and the heel off of the ground, pull on the belt so that the foot is everted, with the outside of the foot being pulled towards you. Hold for 10-20 seconds, and then switch sides.'),
('Power_Clean', 'Power Clean', 'legs', ARRAY['legs','arms','legs','back','back','legs','shoulders','back','arms']::text[], 'barbell', 'strength', 'intermediate', 'Stand with your feet slightly wider than shoulder width apart and toes pointing out slightly. Squat down and grasp bar with a closed, pronated grip. Your hands should be slightly wider than shoulder width apart outside knees with elbows fully extended. Place the bar about 1 inch in front of your shins and over the balls of your feet. Your back should be flat or slightly arched, your chest held up and out and your shoulder blades should be retracted. Keep your head in a neutral position (in line '),
('Power_Clean_from_Blocks', 'Power Clean from Blocks', 'legs', ARRAY['legs']::text[], 'barbell', 'olympic weightlifting', 'intermediate', 'With a barbell on boxes of the desired height, take a grip just outside the legs. Lower your hips with the weight focused on the heels, back straight, head facing forward, chest up, with your shoulders just in front of the bar. This will be your starting position. Begin the first pull by driving through the heels, extending your knees. Your back angle should stay the same, and your arms should remain straight. As the bar approaches the mid-thigh position, begin extending through the hips. In a j'),
('Power_Jerk', 'Power Jerk', 'legs', ARRAY['core','legs','legs','legs','shoulders','arms']::text[], 'barbell', 'olympic weightlifting', 'expert', 'Standing with the weight racked on the front of the shoulders, begin with the dip. With your feet directly under your hips, flex the knees without moving the hips backward. Go down only slightly, and reverse direction as powerfully as possible. Drive through the heels create as much speed and force as possible, and be sure to move your head out of the way as the bar leaves the shoulders. At this moment as the feet leave the floor, the feet must be placed into the receiving position as quickly as'),
('Power_Partials', 'Power Partials', 'shoulders', ARRAY[]::text[], 'dumbbell', 'strength', 'beginner', 'Stand up with your torso upright and a dumbbell on each hand being held at arms length. The elbows should be close to the torso. The palms of the hands should be facing your torso. Your feet should be about shoulder width apart. This will be your starting position. Keeping your arms straight and the torso stationary, lift the weights out to your sides until they are about shoulder level height while exhaling. Feel the contraction for a second and begin to lower the weights back down to the start')
